#include<algorithm>
using namespace std;

typedef long long int ll;
static const int MAX_N = 2000;

int N;
ll A[MAX_N];
ll memo[MAX_N * 2 * MAX_N]; // Changed to single-dimensional array

ll memoize(int i, int j) {
    if (memo[i * (2 * MAX_N) + j] != -1) return memo[i * (2 * MAX_N) + j]; // Updated index calculation

    int i2 = (i == N - 1 ? 0 : i + 1);
    int j2 = (j == 0 ? N - 1 : j - 1);
    int itv = (i > j ? N + j - i : j - i);

    if ((N - itv) % 2 == 1) {
        return memo[i * (2 * MAX_N) + j] = (i == j) ? A[i] : max(memoize(i2, j) + A[i], memoize(i, j2) + A[j]);
    } else {
        return memo[i * (2 * MAX_N) + j] = (i == j) ? 0LL : (A[i] > A[j] ? memoize(i2, j) : memoize(i, j2));
    }
}

int main() {
    scanf("%d", &N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);
    fill(memo, memo + MAX_N * 2 * MAX_N, -1); // Updated fill for new memo array
    ll res = 0LL;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            res = max(res, memoize(i, j));
        }
    }
    printf("%lld\n", res);
    return 0;
}

